create extension if not exists pgcrypto;
create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 100),owner_user_id uuid not null unique references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.workspace_members(workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('owner','admin','member')),created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create index if not exists workspace_members_user_idx on public.workspace_members(user_id);
create table if not exists public.game_rooms(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,host_user_id uuid not null references auth.users(id) on delete cascade,code text not null unique check(code ~ '^[A-HJ-NP-Z2-9]{7}$'),title text not null check(char_length(title) between 3 and 80),objective text not null check(char_length(objective) between 10 and 1000),objective_type text not null check(objective_type in ('research','marketing','sponsorship','partnership','product','resale','licensing')),status text not null default 'lobby' check(status in ('lobby','active','completed','cancelled')),phase text not null default 'lobby' check(phase in ('lobby','briefing','research','strategy','boss_review','correction','deal_room','results','completed')),current_round integer not null default 1 check(current_round>=1),max_rounds integer not null default 5 check(max_rounds in (3,5,7,10)),max_players integer not null default 8 check(max_players between 2 and 8),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.game_players(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.game_rooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,display_name text not null check(char_length(display_name) between 2 and 32),role text not null default 'player' check(role in ('owner','player','spectator')),team_id text not null default 'alpha',ready boolean not null default false,score integer not null default 0 check(score>=0),joined_at timestamptz not null default now(),unique(room_id,user_id));
create table if not exists public.game_events(room_id uuid not null references public.game_rooms(id) on delete cascade,sequence integer not null check(sequence>=1),event_type text not null,actor_user_id uuid references auth.users(id) on delete set null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),primary key(room_id,sequence));
create or replace function public.ensure_personal_workspace(p_user_id uuid,p_name text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin insert into public.workspaces(name,owner_user_id) values(left(coalesce(nullif(trim(p_name),''),'Personal Workspace'),100),p_user_id) on conflict(owner_user_id) do update set owner_user_id=excluded.owner_user_id returning id into v_id; insert into public.workspace_members(workspace_id,user_id,role) values(v_id,p_user_id,'owner') on conflict(workspace_id,user_id) do nothing; return v_id; end; $$;
create or replace function public.create_game_room(p_workspace_id uuid,p_host_user_id uuid,p_display_name text,p_title text,p_objective text,p_objective_type text,p_max_players integer,p_max_rounds integer) returns public.game_rooms language plpgsql security definer set search_path=public as $$ declare v_room public.game_rooms;v_code text;v_alphabet constant text:='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';v_attempt integer;begin if not exists(select 1 from public.workspace_members where workspace_id=p_workspace_id and user_id=p_host_user_id) then raise exception 'WORKSPACE_ACCESS_DENIED';end if;for v_attempt in 1..10 loop v_code:='';for i in 1..7 loop v_code:=v_code||substr(v_alphabet,floor(random()*length(v_alphabet)+1)::integer,1);end loop;exit when not exists(select 1 from public.game_rooms where code=v_code);end loop;if exists(select 1 from public.game_rooms where code=v_code) then raise exception 'ROOM_CODE_GENERATION_FAILED';end if;insert into public.game_rooms(workspace_id,host_user_id,code,title,objective,objective_type,status,phase,current_round,max_players,max_rounds) values(p_workspace_id,p_host_user_id,v_code,trim(p_title),trim(p_objective),p_objective_type,'lobby','lobby',1,p_max_players,p_max_rounds) returning * into v_room;insert into public.game_players(room_id,user_id,display_name,role,team_id,ready) values(v_room.id,p_host_user_id,trim(p_display_name),'owner','alpha',true);insert into public.game_events(room_id,sequence,event_type,actor_user_id,payload) values(v_room.id,1,'room_created',p_host_user_id,jsonb_build_object('title',v_room.title,'code',v_room.code));return v_room;end; $$;
create or replace function public.join_game_room(p_code text,p_user_id uuid,p_display_name text) returns public.game_rooms language plpgsql security definer set search_path=public as $$ declare v_room public.game_rooms;v_count integer;v_seq integer;begin select * into v_room from public.game_rooms where code=upper(trim(p_code)) for update;if not found or v_room.status<>'lobby' then raise exception 'ROOM_NOT_FOUND';end if;if exists(select 1 from public.game_players where room_id=v_room.id and user_id=p_user_id) then return v_room;end if;select count(*) into v_count from public.game_players where room_id=v_room.id;if v_count>=v_room.max_players then raise exception 'ROOM_FULL';end if;insert into public.game_players(room_id,user_id,display_name,role,team_id,ready) values(v_room.id,p_user_id,trim(p_display_name),'player','alpha',false);select coalesce(max(sequence),0)+1 into v_seq from public.game_events where room_id=v_room.id;insert into public.game_events(room_id,sequence,event_type,actor_user_id,payload) values(v_room.id,v_seq,'player_joined',p_user_id,jsonb_build_object('displayName',trim(p_display_name)));return v_room;end; $$;
revoke all on function public.ensure_personal_workspace(uuid,text) from public,anon,authenticated;
revoke all on function public.create_game_room(uuid,uuid,text,text,text,text,integer,integer) from public,anon,authenticated;
revoke all on function public.join_game_room(text,uuid,text) from public,anon,authenticated;
grant execute on function public.ensure_personal_workspace(uuid,text) to service_role;
grant execute on function public.create_game_room(uuid,uuid,text,text,text,text,integer,integer) to service_role;
grant execute on function public.join_game_room(text,uuid,text) to service_role;
create or replace function public.is_workspace_member(check_workspace_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=check_workspace_id and m.user_id=auth.uid()); $$;
create or replace function public.is_room_member(check_room_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.game_players p where p.room_id=check_room_id and p.user_id=auth.uid()); $$;
revoke all on function public.is_workspace_member(uuid) from public,anon;
revoke all on function public.is_room_member(uuid) from public,anon;
grant execute on function public.is_workspace_member(uuid) to authenticated,service_role;
grant execute on function public.is_room_member(uuid) to authenticated,service_role;
alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.game_rooms enable row level security;alter table public.game_players enable row level security;alter table public.game_events enable row level security;
grant select on public.workspaces,public.workspace_members,public.game_rooms,public.game_players,public.game_events to authenticated;
drop policy if exists "workspace member reads" on public.workspaces;create policy "workspace member reads" on public.workspaces for select to authenticated using(public.is_workspace_member(id));
drop policy if exists "member list reads" on public.workspace_members;create policy "member list reads" on public.workspace_members for select to authenticated using(user_id=auth.uid() or public.is_workspace_member(workspace_id));
drop policy if exists "room members read rooms" on public.game_rooms;create policy "room members read rooms" on public.game_rooms for select to authenticated using(public.is_room_member(id));
drop policy if exists "room members read players" on public.game_players;create policy "room members read players" on public.game_players for select to authenticated using(public.is_room_member(room_id));
drop policy if exists "room members read events" on public.game_events;create policy "room members read events" on public.game_events for select to authenticated using(public.is_room_member(room_id));
